 import{onMount}from"svelte";import{inspectorStore}from"../../appshell/lib/inspector-core";import{setInspectorOpen,shellStore}from"../../appshell/lib/store";let v=$state(0),iv=$state(0);onMount(()=>{const a=shellStore.subscribe(()=>v++),b=inspectorStore.subscribe(()=>iv++);return()=>{a();b()}});let open=$derived((v,shellStore.getInspectorOpen()));let focused=$derived((v,shellStore.getFocused()));let appId=$derived(focused?shellStore.getWindow(focused)?.app:null);let info=$derived((iv,inspectorStore.get(appId)));
